  min-width: 72px;
  max-width: 160px;
  height: 44px;
}

.sparkline svg {
  display: block;
  overflow: visible;
}

/* --------------------------------------------------------------- charts */

.chart {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 0;
}

.legend {
  display: flex;
  gap: 16px;
  height: 24px;
  align-items: center;
  font-size: 12px;
  color: var(--ink-2);
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.key-line {
  display: inline-block;
  width: 12px;
  height: 2px;
  border-radius: 1px;
}

.key-swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 2px;
}

.line-svg {
  display: block;
  outline: none;
}

.line-svg:focus-visible {
  outline: 2px solid var(--s1);
  outline-offset: 2px;
  border-radius: 4px;
}

.gridline {
  stroke: var(--grid-line);
  stroke-width: 1;
}

.baseline {
  stroke: var(--baseline);
  stroke-width: 1;
}

.crosshair {
  stroke: var(--baseline);
  stroke-width: 1;
}

.marker {
  stroke: var(--surface);
  stroke-width: 2;
}

.axis-text {
  fill: var(--ink-3);
  font-size: 11px;
}

/* Ranked bars */

.bars {
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  height: 100%;
  min-height: 0;
}

.bar-row {
  display: grid;
  grid-template-columns: minmax(110px, 34%) 1fr;
  align-items: center;
  gap: 12px;
  outline: none;
  cursor: default;
}

.bar-row:focus-visible {
  box-shadow: 0 0 0 2px var(--s1);
  border-radius: 6px;
}

.bar-name {
  overflow: hidden;
  font-size: 13px;
  color: var(--ink-2);
  white-space: nowrap;
  text-overflow: ellipsis;
}

.bar-track {
  display: flex;
  align-items: center;
  min-width: 0;
}

.bar {
  flex: none;
  height: 20px; /* <= 24px, per marks spec */
  min-width: 2px;
  background: var(--s1);
  border-radius: 0 4px 4px 0; /* rounded data end, square at baseline */
  transition: filter 0.12s ease;
}

.bar-row[data-active='true'] .bar {
  filter: brightness(1.12);
}

.bar-value {
  flex: none;
  width: 84px;
  padding-left: 8px;
  font-size: 13px;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* Tall segmented bar */

.segmented-wrap {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 18px;
  height: 100%;
  min-height: 0;
}

.segmented {
  display: flex;
  gap: 2px; /* surface gap between touching blocks */
  height: 28px;
}

.segment {
  flex-basis: 0;
  flex-shrink: 1;
  display: flex;
  align-items: center;
  min-width: 2px;
  padding-left: 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  outline: none;
}

.segment:focus-visible {
  box-shadow: 0 0 0 2px var(--surface), 0 0 0 4px var(--ink);
}

.segment:hover {
  filter: brightness(1.08);
}

.segment-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: var(--ink-2);
}

.segment-legend li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* Meter */

.meter {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  height: 100%;
}

.meter-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.meter-value {
  font-size: 28px;
  font-weight: 600;
}

.meter-sub,
.meter-foot {
  font-size: 12px;
  color: var(--ink-2);
}

.meter-track {
  height: 10px;
  overflow: hidden;
  background: var(--track);
  border-radius: 5px;
}

.meter-fill {
  height: 100%;
  background: var(--s1);
  border-radius: 5px;
}

/* Tables */

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.data-table th,
.data-table td {
  padding: 9px 8px;
  text-align: left;
  border-bottom: 1px solid var(--grid-line);
}

.data-table th {
  position: sticky;
  top: 0;
  background: var(--surface);
  font-size: 12px;
  font-weight: 500;
  color: var(--ink-3);
}

.data-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* Tooltip: floating, follows the pointer, never clipped by a card. */

.tooltip {
  position: fixed;
  z-index: 1000;
  pointer-events: none;
  min-width: 140px;
  padding: 8px 10px;
  background: #ffffff;
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 4px 14px rgba(11, 11, 11, 0.12);
  font-size: 12px;
  color: var(--ink-2);
}

.tt-title {
  margin-bottom: 4px;
  color: var(--ink-3);
}

.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.tt-name {
  flex: 1;
  color: var(--ink-2);
}

.tt-value {
  color: var(--ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* -------------------------------------------------------- narrow screens */

@media (max-width: 760px) {
  .dash-page {
    padding: 16px;
  }
}

