  font-size: 12px;
  font-weight: 500;
  color: var(--ink-3);
}

.data-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* Tooltip: floating, follows the pointer, never clipped by a card. */

.tooltip {
  position: fixed;
  z-index: 1000;
  pointer-events: none;
  min-width: 140px;
  padding: 8px 10px;
  background: #ffffff;
  border: 1px solid var(--border);
  border-radius: 8px;
  box-shadow: 0 4px 14px rgba(11, 11, 11, 0.12);
  font-size: 12px;
  color: var(--ink-2);
}

.tt-title {
  margin-bottom: 4px;
  color: var(--ink-3);
}

.tt-row {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.tt-name {
  flex: 1;
  color: var(--ink-2);
}

.tt-value {
  color: var(--ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* -------------------------------------------------------- narrow screens */

@media (max-width: 760px) {
  .dash-page {
    padding: 16px;
  }
}

